cascade", "score": 0.736, "reached_via": ["request matches RQC:RQC-139 (0.76); FAM:SF-CHT-052 auto_addresses_question RQC:RQC-139", "request matches DS:Player_absence_spells (0.77); FAM:SF-CHT-052 auto_uses_dataset DS:Player_absence_spells"], "attributes": {"observed_research_question": "Play-type replacement similarity vs absorb/cascade", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Having a similar-profile teammate separates absorption from cascade when a player sits.", "observed_result": "mean sim ABSORBED +0.863 vs CASCADE +0.848; Spearman(sim, -gap)=-0.19 (wrong-signed). Embiid 23-24 cascades with Reed sim 0.94.", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Similarity does not separate absorption from cascade; almost always findable.", "observed_sample_and_power": "NOT_RECORDED", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null", "observed_failure_type": "B_powered_null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-005"}, {"rel": "auto_related_family", "node": "FAM:SF-CHT-032"}, {"rel": "auto_related_family", "node": "FAM:SF-CHT-086"}]}], "n_results": 10}

